/**
 * A Hebrew, right-to-left view: the page is `dir="rtl"` and `lang="he"`, so the kit's logical
 * spacing and alignment mirror, and the theme binds a font that carries both Latin and Hebrew.
 * Subset the font to Latin + Hebrew before adding it (for example from @fontsource), so the
 * bundle stays small. Each grouped row of one governed metric becomes a card.
 */
import { createRoot } from 'react-dom/client';
import {
  Card,
  CardContent,
  CardHeader,
  CardTitle,
  EmptyState,
  Icon,
  Section,
  Skeleton,
  SurfaceApp,
  useMetric,
} from '@cynap/surface-sdk';

import { theme } from './theme';
import './styles.css';

/** A metric grouped by one dimension. Replace it. */
const METRIC = 'REPLACE_WITH_METRIC';

type Row = Record<string, unknown>;
const labelOf = (row: Row) => String(row.label ?? '');
const valueOf = (row: Row) => (typeof row.value === 'number' ? row.value : Number(row.value) || 0);
const number = new Intl.NumberFormat('he-IL');

function Summary() {
  const metric = useMetric(METRIC);
  const rows = [...(metric.data?.rows ?? [])] as Row[];

  return (
    <div dir="rtl" lang="he" className="tpl-page">
      <Section title="סיכום פעילות">
        {metric.state === 'loading' ? (
          <Skeleton height={120} />
        ) : rows.length === 0 ? (
          <EmptyState title="אין נתונים עדיין" />
        ) : (
          <div className="tpl-cards">
            {rows.map((row) => (
              <Card key={labelOf(row)}>
                <CardHeader>
                  <Icon name="activity" />
                  <CardTitle>{labelOf(row)}</CardTitle>
                </CardHeader>
                <CardContent>
                  <p className="tpl-figure">{number.format(valueOf(row))}</p>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </Section>
    </div>
  );
}

const root = document.getElementById('root');
if (root) {
  createRoot(root).render(
    <SurfaceApp info={{ name: 'rtl-hebrew', version: '1.0.0' }} theme={theme}>
      <Summary />
    </SurfaceApp>
  );
}

