/**
 * The theme: the one file allowed to hold colour literals. Replace the values with the brand's.
 * `fonts.sans` is a static import of a Latin + Hebrew subset in this surface (add
 * hebrew-sans.woff2 beside this file); the SDK registers it and names its family.
 */
import { defineSurfaceTheme } from '@cynap/surface-sdk';

import hebrewSans from './hebrew-sans.woff2';

export const theme = defineSurfaceTheme({
  fonts: { sans: hebrewSans },
  density: 'comfortable',
  motion: 'subtle',
  light: {
    '--color-ring-primary': '#1d4ed8',
    '--border-radius-md': '8px',
  },
  dark: {
    '--color-ring-primary': '#60a5fa',
    '--border-radius-md': '8px',
  },
});

