/* Layout only, in logical properties so it mirrors under dir="rtl". */
.tpl-page {
  display: grid;
  gap: 1rem;
  padding-block: 1rem;
  padding-inline: 1rem;
}

.tpl-cards {
  display: grid;
  gap: 1rem;
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
}

.tpl-figure {
  font-size: 2rem;
  text-align: start;
}
